POSTS = []

POSTS.append(dict(
 slug="customer-ghosted-after-quote",
 card="Why homeowners go quiet after a quote, the three message follow up that gets replies, and how to stop handing your drawings to a cheaper competitor.",
 title="Customer Ghosted After a Quote? The Follow Up That Works",
 desc="Customer ghosted you after a quote? Why homeowners go quiet, a three message follow up text that gets replies, and how to stop wasting hours quoting.",
 h1="Ghosted after a quote? *Here is what to send.*",
 lede="Most homeowners who go quiet after a quote are not being rude. They got several quotes, someone was cheaper or quicker, and saying no feels awkward, so they say nothing. You cannot stop it completely, but a ballpark price first, an expiry date on every quote and a short follow up sequence win back a surprising share.",
 ticks=["Why customers go quiet", "A three message follow up you can copy", "How to protect hours of quoting work"],
 html="""<h2 id="why">Why do customers ghost after a quote?</h2><p>Contractors on Reddit put the number anywhere from one in five to well over half. Homeowners explain it from the other side in the same threads:</p><ul><li><strong>They got several quotes</strong> and went with someone else, usually cheaper or faster.</li><li><strong>Saying no feels awkward.</strong> Some worry about an angry reply, so silence feels safer.</li><li><strong>The price shocked them</strong> and they need time, or the project is now on hold.</li><li><strong>Life got in the way.</strong> The quote sits in an inbox under fifty other emails.</li></ul><p>Only the last two are winnable, but they are more common than most trades think.</p><h2 id="before">Stop it before the quote: three habits</h2><ol><li><strong>Give a ballpark first.</strong> On the first call, give a rough range. People who cannot afford it drop out before you spend six hours measuring and pricing.</li><li><strong>Put an expiry date on every quote.</strong> Seven to fourteen days is common. It gives you a natural reason to follow up and nudges people to decide.</li><li><strong>Keep the valuable parts until there is a deposit.</strong> Trades repeatedly report homeowners taking detailed drawings and specs to a cheaper builder. Quote the job; hand over the design work once they commit.</li></ol><h2 id="follow-up">The follow up sequence that gets replies</h2><p>Short, friendly and easy to answer. Send by text if that is how they first contacted you.</p><p><strong>Day 2:</strong> “Hi Sam, just checking the quote for your driveway came through okay. Happy to walk you through any of it. Cheers, Jake.”</p><p><strong>Day 6:</strong> “Hi Sam, a quick heads up: the price on your quote is held until Friday. If the timing or budget has changed, just let me know and I can look at options.”</p><p><strong>Day 12:</strong> “Hi Sam, I will close this one off on my side so I am not chasing you. If you go ahead with someone else, no hard feelings at all, and if anything changes I am happy to help.”</p><p>The last message works because it makes saying no easy. A lot of people reply to it, and some of those replies are “sorry, still keen, can we start next month?”</p><h2 id="phone">Call, do not just email</h2><p>A two minute phone call on day two or three wins more work than any email. You learn whether price, timing or trust is the problem, and you can often fix it on the spot with a smaller scope, a payment plan or a later start date.</p><h2 id="trust">Make your quote the easy choice</h2><p>When a homeowner compares three quotes, they also compare the businesses. The trade with recent Google reviews, photos of similar jobs and a clear website looks like the safer bet even at a higher price. That is the quiet reason some trades get ghosted less: the homeowner checked them out and felt sure. See <a href="/guides/what-a-trade-website-needs/">what a trade website needs</a> to win that comparison.</p>""",
 checklist=["Give a rough price range on the first call", "Add a 7 to 14 day expiry date to every quote", "Keep drawings and detailed designs until a deposit is paid", "Follow up by text on day 2", "Call on day 2 or 3", "Send a price held reminder around day 6", "Close it off politely around day 12", "Track how many quotes you win and lose"],
 faq=[("How long should I wait to follow up on a quote?", "Two days is a good first follow up. Most trades send two or three messages over about two weeks, then close it off politely."),
      ("Should a quote have an expiry date?", "Yes. Seven to fourteen days is common. It protects you from material price rises and gives the customer a reason to decide."),
      ("Is it rude to follow up on a quote?", "No. Most homeowners expect it, and many are glad of the reminder. Keep it short and make it easy for them to say no."),
      ("How do I stop people using my drawings with another builder?", "Quote the job without handing over detailed drawings or designs, and charge a design fee or take a deposit before you release them."),
      ("Why do I lose quotes to cheaper contractors?", "Often because the homeowner cannot see the difference. Reviews, photos of similar work and a clear explanation of what is included help justify a higher price.")],
 links=["how-to-deal-with-time-wasters", "should-you-charge-for-quotes", "how-to-get-paid-on-time", "/guides/what-a-trade-website-needs/"],
))

POSTS.append(dict(
 slug="how-to-deal-with-time-wasters",
 card="Four questions to ask on the phone that filter out tyre kickers before you drive out, and how your website can screen them for you.",
 title="How to Deal With Tyre Kickers and Time Wasters",
 desc="How contractors filter out tyre kickers and time wasters before driving out to quote: four phone questions, photos first and ballpark prices.",
 h1="Four questions that filter *time wasters.*",
 lede="Trades lose countless hours driving to quotes for people who were never going to go ahead. The fix is not to quote less, it is to qualify faster: ask about budget, timing, photos and who decides, before you get in the van.",
 ticks=["Four questions for every enquiry", "Photos and ballparks before site visits", "How your website can screen for you"],
 html="""<h2 id="the-cost">What time wasters really cost you</h2><p>A site visit is rarely just an hour. Add driving, measuring, pricing and writing the quote, and a big job can take most of a day. If half of those quotes go nowhere, that is days every month spent working for free. Contractors in forums call these people tyre kickers, or tire kickers in the USA, and the most upvoted advice is always the same: filter them on the phone.</p><h2 id="four-questions">Four questions to ask before you drive out</h2><ol><li><strong>“What sort of budget do you have in mind?”</strong> If they will not say, give a range and watch the reaction. “Jobs like this usually land between $8,000 and $12,000. Does that sound about right?”</li><li><strong>“When are you hoping to get it done?”</strong> “Sometime next year” and “just getting ideas” tell you a lot.</li><li><strong>“Could you send a few photos first?”</strong> Serious customers send them within the hour. It also lets you spot problems and price more accurately.</li><li><strong>“Is anyone else involved in the decision?”</strong> If a partner, landlord or body corporate decides, get them at the site visit or you will be quoting twice.</li></ol><p>Asked in a friendly way, none of these put off a genuine customer. They show you are organised.</p><h2 id="ballpark">Give ballpark prices early</h2><p>A rough range on the first call is the single most effective filter. People who cannot afford the job drop out before you have spent anything. People who stay have already accepted roughly what it costs, which makes the final quote easier to accept too.</p><h2 id="video">Use photos and video calls</h2><p>For many jobs, photos or a five minute video call are enough for a range or even a firm price. Save site visits for jobs that are clearly real and clearly worth it.</p><h2 id="website">Let your website do the screening</h2><p>A good trade website filters before the phone even rings:</p><ul><li>A <strong>“typical jobs”</strong> section with rough starting prices or ranges, so people self select.</li><li>A <strong>quote form</strong> that asks for the suburb, the job type, the timeframe and photos.</li><li>Clear <strong>service areas</strong>, so you stop getting calls from two hours away.</li><li><strong>Real project photos</strong>, so people know the standard (and the price level) they are calling about.</li></ul><p>See <a href="/guides/what-a-trade-website-needs/">what a trade website needs</a> for the full list. Fewer, better enquiries beat a ringing phone full of maybes.</p>""",
 checklist=["Ask about budget on every first call", "Ask when they want the work done", "Ask for photos before any site visit", "Ask who makes the decision", "Give a ballpark range early", "Use video calls for smaller jobs", "Add a quote form that asks for photos and timing", "List your service areas clearly on your website"],
 faq=[("What is a tyre kicker in construction?", "Someone who asks for quotes with no real intention or budget to go ahead. They often collect several quotes just to get ideas."),
      ("Is it okay to ask a customer their budget?", "Yes. Most people expect it. If they will not say, give a typical range for similar jobs and ask if it sounds right."),
      ("Should I quote from photos?", "For many smaller jobs, photos or a video call are enough for a range or a firm price. Visit only when the job needs it."),
      ("How do I stop getting calls from outside my area?", "List your service areas clearly on your website and Google Business Profile, and ask for the suburb or town on your quote form."),
      ("Should I charge for site visits?", "Many trades charge a small fee credited against the job if they go ahead. It works well for some trades and areas and not others.")],
 links=["should-you-charge-for-quotes", "customer-ghosted-after-quote", "how-to-get-more-customers", "/guides/what-a-trade-website-needs/"],
))

POSTS.append(dict(
 slug="should-you-charge-for-quotes",
 card="When a call out fee credited against the job filters out time wasters, when it backfires, and how to word it so customers accept it.",
 title="Should Contractors Charge for Quotes?",
 desc="Should you charge for quotes as a contractor? When a small call out fee credited to the job works, when it backfires, and how to explain it to customers.",
 h1="Should you charge *for quotes?*",
 lede="Charging a small fee for a site visit, credited back if the customer goes ahead, is one of the most recommended ways to stop free quoting from eating your week. It works best on complex jobs and for established businesses. On simple jobs in a competitive area, a free quote may still win you more work.",
 ticks=["When a quote fee works", "When it backfires", "How to word it"],
 html="""<h2 id="short-answer">Should you charge for quotes?</h2><p>For many trades, yes, at least for some jobs. Contractors in forums report that a fee of roughly $50 to $100 for the visit, credited against the job, weeds out a surprising number of people who were never going to go ahead. Serious customers rarely object because they get the money back when they book.</p><h2 id="when-it-works">When a quote fee works</h2><ul><li><strong>Complex jobs</strong> where pricing takes hours: renovations, landscaping designs, extensions, commercial work.</li><li><strong>Diagnosis</strong> is part of the visit: finding a leak, an electrical fault or a heating problem is real work.</li><li><strong>You are busy</strong> and have more enquiries than time.</li><li><strong>You have reviews and a reputation</strong>, so customers already want you specifically.</li></ul><h2 id="when-it-backfires">When it backfires</h2><ul><li><strong>Simple, common jobs</strong> where three competitors quote for free from photos.</li><li><strong>You are new</strong> with few reviews; a fee can send people to someone with a free quote.</li><li><strong>The fee is not explained</strong>, so it feels like a charge for nothing.</li></ul><h2 id="middle-ground">The middle ground most trades use</h2><ol><li><strong>Free ballpark</strong> over the phone or from photos for everyone.</li><li><strong>Free site visit</strong> for straightforward jobs that are clearly real.</li><li><strong>Paid visit or design fee</strong>, credited to the job, for complex work or detailed drawings.</li></ol><p>This keeps the door open for easy jobs while protecting the hours that big quotes take.</p><h2 id="wording">How to explain a quote fee</h2><p>Say it plainly and early: “For jobs like this we charge $80 for the site visit, because it takes a couple of hours to measure and price properly. If you go ahead, the $80 comes off your invoice.”</p><p>Put the same line on your website next to your quote form, so nobody is surprised. Clear expectations are what make customers accept it.</p><h2 id="trust">Why trust makes a fee easier</h2><p>People pay for a visit from a business they already trust. Recent Google reviews, photos of similar jobs and a professional website make a small fee feel reasonable instead of risky. See <a href="/guides/local-seo-for-trades/">how trades get found on Google</a>.</p>""",
 checklist=["Decide which jobs get a free ballpark", "Decide which jobs need a paid visit", "Set a fee that covers your time", "Always credit it against the job", "Explain the fee on the first call", "Put the fee policy next to your quote form", "Charge separately for detailed drawings", "Track how many paid visits turn into jobs"],
 faq=[("How much should I charge for a quote?", "Many trades charge roughly $50 to $100 for a site visit, credited against the job. Complex design work is often charged separately."),
      ("Is it normal to charge for a quote?", "It is increasingly common for complex jobs and diagnosis. Simple jobs are still usually quoted for free."),
      ("Will charging for quotes lose me customers?", "You will lose some, mostly people who were not serious. If you are new or in a very competitive trade, test it on bigger jobs first."),
      ("Should the quote fee be refundable?", "The most common approach is to credit it against the job if the customer goes ahead, rather than refund it if they do not."),
      ("Can I charge for drawings and designs?", "Yes. Many builders and landscapers charge a design fee, which also stops customers taking your plans to a cheaper competitor.")],
 links=["how-to-deal-with-time-wasters", "customer-ghosted-after-quote", "how-to-get-paid-on-time", "/guides/what-a-trade-website-needs/"],
))
